import { readFileSync } from "node:fs";
import { inflateRawSync } from "node:zlib";

const buf = readFileSync(process.argv[2]);
// find EOCD
let eo = buf.length - 22;
while (eo >= 0 && buf.readUInt32LE(eo) !== 0x06054b50) eo--;
const count = buf.readUInt16LE(eo + 10);
let off = buf.readUInt32LE(eo + 16);
const want = process.argv[3];
for (let i = 0; i < count; i++) {
  const nlen = buf.readUInt16LE(off + 28), elen = buf.readUInt16LE(off + 30), clen = buf.readUInt16LE(off + 32);
  const method = buf.readUInt16LE(off + 10);
  const csize = buf.readUInt32LE(off + 20), usize = buf.readUInt32LE(off + 24);
  const lho = buf.readUInt32LE(off + 42);
  const name = buf.toString("utf8", off + 46, off + 46 + nlen);
  const flags = buf.readUInt16LE(off + 8);
  if (!want) console.log(`${name}\tmethod=${method}\tflags=0x${flags.toString(16)}\tcsize=${csize}\tusize=${usize}`);
  else if (name === want || name.endsWith(want)) {
    const ln = buf.readUInt16LE(lho + 26), le = buf.readUInt16LE(lho + 28);
    const start = lho + 30 + ln + le;
    const raw = buf.subarray(start, start + csize);
    const data = method === 0 ? raw : inflateRawSync(raw);
    console.log(`### ${name}`);
    console.log(data.toString("utf8"));
  }
  off += 46 + nlen + elen + clen;
}
EOF
