    listed.writeUInt32LE(0x02014b50, 0);
    listed.writeUInt16LE(20, 4);
    listed.writeUInt16LE(20, 6);
    listed.writeUInt16LE(0, 8);
    listed.writeUInt16LE(0, 10);
    listed.writeUInt16LE(0, 12);
    listed.writeUInt16LE(DOS_DATE, 14);
