const here = dirname(fileURLToPath(import.meta.url));
const plugin = join(here, "..", "com.scrthq.runlog.sdPlugin");
const repo = join(here, "..", "..");

const MANIFEST = JSON.parse(readFileSync(join(plugin, "manifest.json"), "utf8"));

